css:
:root {
  --text: #0d0d0d;
  --animate-bg: rgba(243, 243, 243, 0.9);
  --animate-bg-tint: #bfc0cb;
  --animate-bg-hover: #eae9e9;
  --animate-text: #17181c;
  --skeleton: #eeeeef;
  --material-bg: #ffffff;
  --material-shadow: 0 4px 42px 0 rgba(0, 0, 0, 0.06),
        0 2px 6px 0 rgba(0, 0, 0, 0.05),
        0 0 0 1px rgba(0, 0, 0, 0.06);
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",
        Roboto, Helvetica, Arial, sans-serif;
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --p4-dur: 300ms;
  --p4-ease: var(--ease-smooth-out);
}

html[data-theme="dark"] {
  --text: #ffffff;
  --animate-bg: rgba(255, 255, 255, 0.04);
  --animate-bg-tint: transparent;
  --animate-bg-hover: rgba(255, 255, 255, 0.06);
  --animate-bg-pressed: rgba(255, 255, 255, 0.08);
  --animate-text: #e3e3e3;
  --animate-text-disabled: rgba(227, 227, 227, 0.5);
  --skeleton: rgba(238, 238, 239, 0.1);
  --material-bg: #181818;
  --material-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.04),
        inset 0 1px 0 0 rgba(255, 255, 255, 0.04),
        inset 0 0 0 1px rgba(0, 0, 0, 0.06),
        inset 0 -1px 0 0 rgba(0, 0, 0, 0.06),
        inset 0 0 0 1px rgba(196, 196, 196, 0.08);
}

/* The library card, at its size: the stage of the card on library.html. */
:where(.card), :where(.card) *, :where(.card) *::before, :where(.card) *::after { box-sizing: border-box; margin: 0; padding: 0; }
.card { position: relative; width: 296px; height: 260px; color: var(--text); font-family: var(--font-sans); }
.card > .card-stage { inset: 0; width: auto; height: auto; max-width: none; border-radius: 0; }
.card > .card-stage::after { content: none; }

.card-stage {
  position: absolute;
  left: 12px;
  top: 12px;
  width: 296px;
  max-width: calc(100% - 24px);
  height: 260px;
  border-radius: 14px;
  overflow: hidden;
  background: var(--stage-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.card-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px var(--stage-border);
  pointer-events: none;
  z-index: 10;
}
html[data-theme="dark"] .card-stage {
  background: #131313;
}
html[data-theme="dark"] .card-stage::after {
  box-shadow: inset 0 0 0 1px rgba(191, 192, 203, 0.08);
}
.btn-animate {
  appearance: none;
  -webkit-appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 20px;
  height: 36px;
  padding: 6px 12px;
  border: 0;
  border-radius: 40px;
  font-family: var(--font-sans);
  font-weight: 500;
  font-size: 13px;
  line-height: 16px;
  color: var(--animate-text);
  background-color: var(--animate-bg-tint);
  background-image: linear-gradient(90deg, var(--animate-bg) 0%, var(--animate-bg) 100%);
  cursor: pointer;
  white-space: nowrap;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease, filter 0.15s ease;
  z-index: 5;
  flex-shrink: 0;
}
html[data-theme="dark"] .btn-animate {
  background-color: transparent;
  background-image: none;
  background: var(--animate-bg);
}
.btn-animate:hover {
  filter: brightness(0.98);
}
html[data-theme="dark"] .btn-animate:hover {
  background: var(--animate-bg-hover);
  filter: none;
}
html[data-theme="dark"] .btn-animate:active {
  background: var(--animate-bg-pressed);
  filter: none;
}
html[data-theme="dark"] .btn-animate:disabled {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
  cursor: not-allowed;
}
html[data-theme="dark"] .btn-animate:disabled:hover {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
}
.btn-animate:active {
  filter: brightness(0.95);
}
.btn-animate:focus-visible {
  outline: 2px solid var(--animate-text);
  outline-offset: 2px;
}
.btn-animate[data-proto="15"] {
  min-width: 75px;
}
.stage-inner {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 56px;
}
.sk {
  background: var(--skeleton);
  border-radius: 4px;
}
.p4-card {
  width: 220px;
  height: 112px;
  background: var(--material-bg);
  border-radius: 12px;
  box-shadow: var(--material-shadow);
  position: relative;
  overflow: hidden;
  transition: width var(--p4-dur) var(--p4-ease),
        height var(--p4-dur) var(--p4-ease);
}
.p4-card.is-small {
  width: 154px;
  height: 128px;
}
.p4-card .sk {
  position: absolute;
  left: 14px;
  right: 14px;
  background: var(--skeleton);
  border-radius: 4px;
}
.p4-card .sk-1 {
  top: 14px;
  height: 10px;
  right: auto;
  width: calc((100% - 28px) * 0.526);
}
.p4-card .sk-2 {
  top: 28px;
  height: 7px;
}
.p4-card .sk-3 {
  top: 39px;
  height: 7px;
}
.p4-card .sk-4 {
  top: 50px;
  height: 7px;
  right: auto;
  width: calc((100% - 28px) * 0.734);
}
.p4-card .sk-5 {
  top: 78px;
  height: 7px;
}
.p4-card .sk-6 {
  top: 89px;
  height: 7px;
}

@media (max-width: 639px) {
.card-stage {
  right: 12px;
  width: auto;
  max-width: none;
}
}

