        transform: translate(
          calc(var(--p9-distance) * var(--p9-dir-x)),
          calc(var(--p9-distance) * var(--p9-dir-y))
        );
        opacity: 0;
        filter: blur(var(--p9-blur));
      }
      100% { transform: translate(0, 0); opacity: 1; filter: blur(0); }
    }

@keyframes p9-pop-out {
      0%   { transform: translate(0, 0); opacity: 1; filter: blur(0); }
      100% {
        transform: translate(
          calc(var(--p9-distance) * var(--p9-dir-x) * -1),
          calc(var(--p9-distance) * var(--p9-dir-y) * -1)
        );
        opacity: 0;
        filter: blur(var(--p9-blur));
      }
    }

