// Number pop-in: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "9": {
          var p9 = card.querySelector("[data-proto-number]");
          if (!p9) break;
          // Generate a new two-integer-digit + "." + two-decimal number.
          var intPart = Math.floor(Math.random() * 90) + 10;
          var decPart = Math.floor(Math.random() * 100);
          var str = String(intPart) + "." + String(decPart).padStart(2, "0");
          var chars = str.split("");
          var len = chars.length;

          // Snapshot old digits into a ghost so they can play the
          // pop-out animation in parallel with new digits popping in.
          var oldGhost = p9.querySelector(".p9-ghost");
          if (oldGhost) oldGhost.remove();

          var liveChars = p9.querySelectorAll(":scope > .p9-char");
          if (liveChars.length) {
            var ghost = document.createElement("span");
            ghost.className = "p9-ghost";
            liveChars.forEach(function (ch) {
              ghost.appendChild(ch.cloneNode(true));
            });
            p9.appendChild(ghost);
            var p9Dur = readMs("--p9-dur", 500);
            var p9Stag = readMs("--p9-stagger", 70);
            window.setTimeout(function () {
              if (ghost.parentNode) ghost.parentNode.removeChild(ghost);
            }, p9Dur + p9Stag * 2 + 50);
          }

          // Restart the animation class cleanly.
          p9.classList.remove("is-animating");
          p9.querySelectorAll(":scope > .p9-char").forEach(function (el) { el.remove(); });
          chars.forEach(function (ch, i) {
            var span = document.createElement("span");
            span.className = "p9-char";
            span.textContent = ch;
            if (i === len - 2) span.setAttribute("data-stagger", "1");
            else if (i === len - 1) span.setAttribute("data-stagger", "2");
            var ghostEl = p9.querySelector(".p9-ghost");
            if (ghostEl) p9.insertBefore(span, ghostEl);
            else p9.appendChild(span);
          });
          // Force reflow so removing + re-adding the class replays.
          // eslint-disable-next-line no-unused-expressions
          p9.offsetHeight;
          p9.classList.add("is-animating");
          break;
        }
      }
      return;
    }
  });
})();

