// Text states swap: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  // ── Prototype 6 message cycle ────────────────────────────
  var p6Messages = ["Transaction processing...", "Transaction completed"];
  var p6Index = 0;
  var p6Busy = false;

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "6": {
          if (p6Busy) return;
          p6Busy = true;
          var t = card.querySelector("[data-proto-text]");
          var dur = readMs("--p6-dur", 150);
          // Signed offset between the exit-end and the enter-start.
          //   > 0 → empty pause between the two phases
          //   = 0 → back-to-back (default)
          //   < 0 → overlap (cross-fade through opacity:0)
          // Clamped to ≥ 0 so a large negative value just means
          // "swap immediately" rather than scheduling a negative
          // timeout.
          var delay = readMs("--p6-enter-delay", 0);
          var swapAt = Math.max(0, dur + delay);
          t.classList.add("is-exit");
          window.setTimeout(function () {
            p6Index = (p6Index + 1) % p6Messages.length;
            t.textContent = p6Messages[p6Index];
            t.classList.remove("is-exit");
            t.classList.add("is-enter-start");
            void t.offsetHeight;
            t.classList.remove("is-enter-start");
            window.setTimeout(function () { p6Busy = false; }, dur);
          }, swapAt);
          break;
        }
      }
      return;
    }
  });
})();

