// Success check: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "10": {
          var check = card.querySelector("[data-proto-check]");
          if (!check) break;
          // Toggle "in" / "out". On "in" → "out" we add .is-exiting
          // briefly so the soft fade-out animations play; the cold
          // "out" state never runs the exit. To replay "in" cleanly
          // on rapid re-triggers we re-set data-state with a forced
          // reflow so the keyframes restart from offset 0.
          var p10State = check.getAttribute("data-state");
          if (p10State === "in") {
            check.classList.add("is-exiting");
            check.setAttribute("data-state", "out");
            var p10Out = readMs("--p10-out-dur", 500);
            window.setTimeout(function () {
              check.classList.remove("is-exiting");
            }, p10Out + 20);
          } else {
            check.classList.remove("is-exiting");
            check.setAttribute("data-state", "out");
            void check.offsetWidth;
            check.setAttribute("data-state", "in");
          }
          break;
        }
      }
      return;
    }
  });
})();

