// Avatar group hover: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  (function initP11() {
    var roots = document.querySelectorAll("[data-proto-avatars]");
    if (!roots.length) return;
    var docEl = document.documentElement;
    function readNum(name, fb) {
      var v = parseFloat(getComputedStyle(docEl).getPropertyValue(name));
      return isNaN(v) ? fb : v;
    }
    function readEase(name, fb) {
      var v = getComputedStyle(docEl).getPropertyValue(name).trim();
      return v || fb;
    }
    roots.forEach(function (root) {
      var avatars = Array.prototype.slice.call(
        root.querySelectorAll(".p11-avatar")
      );
      function setShifts(activeIdx, phase) {
        var lift    = readNum("--p11-lift", -4);
        var falloff = readNum("--p11-falloff", 0.45);
        var scale   = readNum("--p11-scale", 1.05);
        var ease    = phase === "out"
          ? readEase("--p11-ease-out", "cubic-bezier(0.34, 3.85, 0.64, 1)")
          : readEase("--p11-ease-in",  "cubic-bezier(0.22, 1, 0.36, 1)");
        avatars.forEach(function (el, i) {
          // Set timing-function FIRST so it applies to the
          // transition kicked off by the variable writes below.
          el.style.transitionTimingFunction = ease;
          if (activeIdx == null) {
            el.style.setProperty("--p11-shift", "0px");
            el.style.setProperty("--p11-scale-active", "1");
            return;
          }
          var d = Math.abs(i - activeIdx);
          el.style.setProperty(
            "--p11-shift",
            (lift * Math.pow(falloff, d)).toFixed(3) + "px"
          );
          el.style.setProperty(
            "--p11-scale-active",
            i === activeIdx ? scale.toString() : "1"
          );
        });
      }
      avatars.forEach(function (el, i) {
        el.addEventListener("mouseenter", function () { setShifts(i, "in"); });
      });
      root.addEventListener("mouseleave", function () { setShifts(null, "out"); });
    });
  })();
})();

