// Error state shake: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "12": {
          var wrap = card.querySelector("[data-proto-shake]");
          if (!wrap) break;
          var input = wrap.querySelector(".p12-input");
          var inputEl = wrap.querySelector(".p12-input-el");
          if (!input || !inputEl) break;
          // Always trigger the error state on click — this is the
          // demo, not real validation. Replay the shake by removing
          // the class, forcing reflow, then re-adding.
          wrap.classList.add("is-error");
          input.classList.add("is-error");
          input.classList.remove("is-shaking");
          void input.offsetWidth;
          input.classList.add("is-shaking");
          var shakeMs =
            readMs("--p12-shake-dur-a", 80) * 2 +
            readMs("--p12-shake-dur-b", 60) * 2;
          window.setTimeout(function () {
            input.classList.remove("is-shaking");
          }, shakeMs + 20);
          // Auto-revert: hold the error state long enough to read
          // the message (--p12-revert-hold), then fade border +
          // message back to neutral via CSS (--p12-revert-dur).
          // A previous in-flight revert is cancelled so the timer
          // always tracks the latest Animate.
          if (wrap._revertTimer) window.clearTimeout(wrap._revertTimer);
          var hold = readMs("--p12-revert-hold", 3000);
          wrap._revertTimer = window.setTimeout(function () {
            wrap._revertTimer = null;
            wrap.classList.remove("is-error");
            input.classList.remove("is-error");
          }, shakeMs + hold);
          break;
        }
      }
      return;
    }
  });

  (function initP12() {
    var wraps = document.querySelectorAll("[data-proto-shake]");
    if (!wraps.length) return;
    wraps.forEach(function (wrap) {
      var input = wrap.querySelector(".p12-input");
      var el = wrap.querySelector(".p12-input-el");
      if (!input || !el) return;
      el.addEventListener("input", function () {
        if (wrap._revertTimer) {
          window.clearTimeout(wrap._revertTimer);
          wrap._revertTimer = null;
        }
        wrap.classList.remove("is-error");
        input.classList.remove("is-error");
      });
    });
  })();
})();

