// Input clear with dissolve: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "13": {
          // "Reset text" — re-seed the value so the user can
          // click the × and replay the clear animation without
          // typing anything in.
          var p13Wrap = card.querySelector("[data-proto-p13]");
          if (p13Wrap && p13Wrap._p13Reset) p13Wrap._p13Reset();
          break;
        }
      }
      return;
    }
  });

  (function initP13() {
    var wraps = document.querySelectorAll("[data-proto-p13]");
    if (!wraps.length) return;
    var docEl = document.documentElement;
    var fontSpec = "400 13px Inter, sans-serif";
    var measureCanvas = document.createElement("canvas");
    var measureCtx = measureCanvas.getContext("2d");
    measureCtx.font = fontSpec;
    // Single-color palette flipped per theme: light mode paints
    // black gradients (multiply darkens the input + hairline),
    // dark mode paints white gradients (screen lightens them).
    // The CSS for .p13-search__clear-glow flips the blend-mode
    // for `html[data-theme="dark"]` to keep these two halves in
    // sync.
    function getPalette() {
      var isDark = docEl.getAttribute("data-theme") === "dark";
      return isDark ? [[255, 255, 255]] : [[0, 0, 0]];
    }

    function readNum(name, fb) {
      var v = parseFloat(getComputedStyle(docEl).getPropertyValue(name));
      return isNaN(v) ? fb : v;
    }
    function readEase(name, fb) {
      var v = getComputedStyle(docEl).getPropertyValue(name).trim();
      return v || fb;
    }
    // Parse `cubic-bezier(x1, y1, x2, y2)` into an ease(t) fn.
    function makeCubicBezierEase(easeStr) {
      var m = easeStr.match(
        /cubic-bezier\s*\(\s*([-\d.]+)\s*,\s*([-\d.]+)\s*,\s*([-\d.]+)\s*,\s*([-\d.]+)\s*\)/i
      );
      if (!m) return function (t) { return t; };
      var x1 = parseFloat(m[1]), y1 = parseFloat(m[2]);
      var x2 = parseFloat(m[3]), y2 = parseFloat(m[4]);
      var cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
      var cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
      function sampleX(s) { return ((ax * s + bx) * s + cx) * s; }
      function sampleY(s) { return ((ay * s + by) * s + cy) * s; }
      function derX(s) { return (3 * ax * s + 2 * bx) * s + cx; }
      return function (t) {
        if (t <= 0) return 0;
        if (t >= 1) return 1;
        var s = t;
        for (var i = 0; i < 8; i++) {
          var dx = sampleX(s) - t;
          if (Math.abs(dx) < 1e-6) break;
          var d = derX(s);
          if (d === 0) break;
          s -= dx / d;
        }
        return sampleY(s);
      };
    }

    wraps.forEach(function (wrap) {
      var input  = wrap.querySelector(".p13-search__input");
      var clear  = wrap.querySelector(".p13-search__clear");
      var mirror = wrap.querySelector(".p13-search__text-mirror");
      var fakePh = wrap.querySelector(".p13-search__fake-placeholder");
      var glow   = wrap.querySelector(".p13-search__clear-glow");
      if (!input || !clear || !mirror || !fakePh || !glow) return;

      var defaultText = input.value;
      var isClearing = false;

      function updateMirror() {
        mirror.textContent = input.value.replace(/ /g, "\u00a0");
      }
      function syncHasValue() {
        var has = input.value.length > 0;
        wrap.classList.toggle("has-value", has);
        if (has) updateMirror();
      }
      function buildLayers(text) {
        var inputW = wrap.clientWidth || 280;
        var padLeft = 32;
        var segments = text.split(/(\s+)/);
        var spread = readNum("--p13-glow-spread", 1.5);
        // Re-read the palette per call so a theme switch between
        // clears picks up the right hue without a page reload.
        var palette = getPalette();
        var pLen = palette.length;
        var layers = [];
        var x = 0;
        for (var s = 0; s < segments.length; s++) {
          var seg = segments[s];
          var w = measureCtx.measureText(seg).width;
          if (seg.trim()) {
            var cxPx = padLeft + x + w / 2;
            var hw = Math.max(w * 0.45, 8) * spread;
            var stops = [
              { dx: 0,         rw: hw * 0.8,  rh: 7,   a: 0.22 },
              { dx: hw * 0.45, rw: hw * 0.55, rh: 8,   a: 0.18 },
              { dx: -hw * 0.4, rw: hw * 0.65, rh: 6,   a: 0.16 },
              { dx: hw * 0.15, rw: hw * 0.9,  rh: 5,   a: 0.14 }
            ];
            for (var i = 0; i < stops.length; i++) {
              var l = stops[i];
              var lx = ((cxPx + l.dx) / inputW * 100).toFixed(2);
              var rgb = palette[i % pLen];
              layers.push(
                "radial-gradient(ellipse " + Math.max(l.rw, 2).toFixed(1) +
                "px " + l.rh + "px at " + lx +
                "% 100%, rgba(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + "," +
                l.a.toFixed(3) + "), transparent)"
              );
            }
          }
          x += w;
        }
        return layers.length ? layers.join(", ") : "";
      }

      function clearWithAnimation() {
        if (isClearing) return;
        if (!input.value) return;
        isClearing = true;
        var keepInputFocus = document.activeElement === input;
        updateMirror();
        var bg = buildLayers(mirror.textContent);
        var peakAt = readNum("--p13-glow-peak-at", 0.15);
        var glowOpacity = readNum("--p13-glow-opacity", 0.42);
        var clearDur = readNum("--p13-clear-dur", 1000);
        var textOutDur = readNum("--p13-text-out-dur", 400);
        var textInDur  = readNum("--p13-text-in-dur", 400);
        var outFlyPx   = readNum("--p13-text-out-fly", 12);
        var inFlyPx    = readNum("--p13-text-in-fly", 12);
        var blurPx     = readNum("--p13-blur", 2);
        var glowDelay  = readNum("--p13-glow-delay", 50);
        var easeOut = makeCubicBezierEase(
          readEase("--p13-text-out-ease", "cubic-bezier(0.22, 1, 0.36, 1)")
        );
        var easeIn = makeCubicBezierEase(
          readEase("--p13-text-in-ease", "cubic-bezier(0.22, 1, 0.36, 1)")
        );

        // Snap the input to empty before the animation starts so
        // its own glyphs don't double-render with the mirror that
        // is about to fly up.
        input.value = "";
        wrap.classList.remove("has-value");
        wrap.classList.add("is-clearing");

        // Prime the placeholder above the field; it falls in.
        fakePh.style.transform = "translateY(-" + inFlyPx + "px)";
        fakePh.style.opacity = "0.9";
        fakePh.style.filter = "blur(" + blurPx + "px)";

        glow.style.background = bg;
        glow.style.opacity = "0";

        var start = performance.now();
        (function tick(now) {
          var elapsed = now - start;
          var p = Math.min(1, elapsed / clearDur);
          var tp = Math.min(1, elapsed / textOutDur);
          var e = easeOut(tp);

          // Mirror falls down + blurs + fades; placeholder mirrors
          // the math from above so both elements travel in the
          // same direction.
          mirror.style.transform = "translateY(" + (e * outFlyPx).toFixed(1) + "px)";
          mirror.style.opacity = (1 - e).toFixed(3);
          mirror.style.filter = "blur(" + (e * blurPx).toFixed(1) + "px)";

          var pp = Math.min(1, elapsed / textInDur);
          var pe = easeIn(pp);
          fakePh.style.transform = "translateY(" + (-inFlyPx + pe * inFlyPx).toFixed(1) + "px)";
          fakePh.style.opacity = (0.9 + pe * 0.1).toFixed(3);
          fakePh.style.filter = "blur(" + (blurPx - pe * blurPx).toFixed(1) + "px)";

          // Glow holds at 0 for `glowDelay` ms then runs a triangle
          // envelope (rise → peakAt → fall) over the remaining
          // window so the streak ignites mid-text-fall.
          var g = 0;
          if (elapsed > glowDelay) {
            var remaining = Math.max(1, clearDur - glowDelay);
            var gp = Math.min(1, (elapsed - glowDelay) / remaining);
            g = gp < peakAt
              ? gp / peakAt
              : 1 - (gp - peakAt) / (1 - peakAt);
          }
          glow.style.opacity = (g * glowOpacity).toFixed(3);

          if (p < 1) {
            requestAnimationFrame(tick);
          } else {
            wrap.classList.remove("is-clearing");
            mirror.style.transform = "";
            mirror.style.opacity = "";
            mirror.style.filter = "";
            mirror.textContent = "";
            fakePh.style.transform = "";
            fakePh.style.opacity = "";
            fakePh.style.filter = "";
            glow.style.opacity = "0";
            glow.style.background = "";
            isClearing = false;
            if (keepInputFocus) {
              requestAnimationFrame(function () {
                input.focus({ preventScroll: true });
              });
            }
          }
        })(performance.now());
      }

      function reset() {
        isClearing = false;
        wrap.classList.remove("is-clearing");
        mirror.style.cssText = "";
        fakePh.style.cssText = "";
        glow.style.cssText = "";
        input.value = defaultText;
        syncHasValue();
      }
      wrap._p13Reset = reset;

      // Keep input focus during clear: pointerdown/mousedown fire
      // before the button steals focus, so preventDefault traps it.
      // The click handler also re-focuses synchronously as a final
      // guard against browsers that move focus on the click event.
      function preserveInputFocus(ev) {
        if (document.activeElement === input) ev.preventDefault();
      }
      clear.addEventListener("pointerdown", preserveInputFocus);
      clear.addEventListener("mousedown", preserveInputFocus);
      clear.addEventListener("click", function () {
        var wasFocused = document.activeElement === input ||
                         wrap.contains(document.activeElement);
        clearWithAnimation();
        if (wasFocused) input.focus({ preventScroll: true });
      });
      input.addEventListener("input", syncHasValue);
      syncHasValue();
    });
  })();
})();

css:
:root {
  --text: #0d0d0d;
  --animate-bg: rgba(243, 243, 243, 0.9);
  --animate-bg-tint: #bfc0cb;
  --animate-bg-hover: #eae9e9;
  --animate-text: #17181c;
  --muted: #5e6073;
  --material-bg: #ffffff;
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",
        Roboto, Helvetica, Arial, sans-serif;
  --duration-slow: 400ms;
  --ease-in-out: ease-in-out;
  --blur-small: 2px;
  --p14-pulse-dur: 1000ms;
  --p14-pulse-count: 1;
  --p14-pulse-min: 0.5;
  --p14-reveal-dur: var(--duration-slow);
  --p14-reveal-blur: var(--blur-small);
  --p14-reveal-ease: var(--ease-in-out);
  --p14-skeleton-color: #eeeeee;
}

html[data-theme="dark"] {
  --text: #ffffff;
  --animate-bg: rgba(255, 255, 255, 0.04);
  --animate-bg-tint: transparent;
  --animate-bg-hover: rgba(255, 255, 255, 0.06);
  --animate-bg-pressed: rgba(255, 255, 255, 0.08);
  --animate-text: #e3e3e3;
  --animate-text-disabled: rgba(227, 227, 227, 0.5);
  --muted: #767676;
  --material-bg: #181818;
  --p14-skeleton-color: rgba(255, 255, 255, 0.08);
}

/* The library card, at its size: the stage of the card on library.html. */
:where(.card), :where(.card) *, :where(.card) *::before, :where(.card) *::after { box-sizing: border-box; margin: 0; padding: 0; }
.card { position: relative; width: 296px; height: 260px; color: var(--text); font-family: var(--font-sans); }
.card > .card-stage { inset: 0; width: auto; height: auto; max-width: none; border-radius: 0; }
.card > .card-stage::after { content: none; }

.card-stage {
  position: absolute;
  left: 12px;
  top: 12px;
  width: 296px;
  max-width: calc(100% - 24px);
  height: 260px;
  border-radius: 14px;
  overflow: hidden;
  background: var(--stage-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.card-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px var(--stage-border);
  pointer-events: none;
  z-index: 10;
}
html[data-theme="dark"] .card-stage {
  background: #131313;
}
html[data-theme="dark"] .card-stage::after {
  box-shadow: inset 0 0 0 1px rgba(191, 192, 203, 0.08);
}
.btn-animate {
  appearance: none;
  -webkit-appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 20px;
  height: 36px;
  padding: 6px 12px;
  border: 0;
  border-radius: 40px;
  font-family: var(--font-sans);
  font-weight: 500;
  font-size: 13px;
  line-height: 16px;
  color: var(--animate-text);
  background-color: var(--animate-bg-tint);
  background-image: linear-gradient(90deg, var(--animate-bg) 0%, var(--animate-bg) 100%);
  cursor: pointer;
  white-space: nowrap;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease, filter 0.15s ease;
  z-index: 5;
  flex-shrink: 0;
}
html[data-theme="dark"] .btn-animate {
  background-color: transparent;
  background-image: none;
  background: var(--animate-bg);
}
.btn-animate:hover {
  filter: brightness(0.98);
}
html[data-theme="dark"] .btn-animate:hover {
  background: var(--animate-bg-hover);
  filter: none;
}
html[data-theme="dark"] .btn-animate:active {
  background: var(--animate-bg-pressed);
  filter: none;
}
html[data-theme="dark"] .btn-animate:disabled {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
  cursor: not-allowed;
}
html[data-theme="dark"] .btn-animate:disabled:hover {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
}
.btn-animate:active {
  filter: brightness(0.95);
}
.btn-animate:focus-visible {
  outline: 2px solid var(--animate-text);
  outline-offset: 2px;
}
.btn-animate[data-proto="15"] {
  min-width: 75px;
}
.stage-inner {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 56px;
}
.p14-stage-inner {
  padding-bottom: 0;
}
.p14-card {
  position: relative;
  width: 256px;
  max-width: 100%;
  height: 56px;
  border-radius: 12px;
  background: var(--material-bg);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.06),
        0 1px 2px rgba(0, 0, 0, 0.03);
  overflow: hidden;
}
html[data-theme="dark"] .p14-card {
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.06),
        0 1px 2px rgba(0, 0, 0, 0.4);
}
.p14-skeleton,
.p14-content {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}
.p14-skeleton {
  gap: 6px;
}
.p14-skeleton .p14-sk-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--p14-skeleton-color);
  flex: none;
}
.p14-skeleton .p14-sk-lines {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-left: 4px;
}
.p14-skeleton .p14-sk-name,
.p14-skeleton .p14-sk-email {
  height: 12px;
  border-radius: 4px;
  background: var(--p14-skeleton-color);
}
.p14-skeleton .p14-sk-name {
  width: 100px;
}
.p14-skeleton .p14-sk-email {
  width: 131px;
}
.p14-skeleton.is-pulsing .p14-sk-avatar,
.p14-skeleton.is-pulsing .p14-sk-name,
.p14-skeleton.is-pulsing .p14-sk-email {
  animation: p14-pulse var(--p14-pulse-dur) ease-in-out var(--p14-pulse-count);
}
.p14-skeleton {
  z-index: 1;
  opacity: 1;
  filter: blur(0);
  transition: opacity var(--p14-reveal-dur) var(--p14-reveal-ease),
        filter  var(--p14-reveal-dur) var(--p14-reveal-ease);
  transition-delay: 0ms;
}
.p14-content {
  z-index: 2;
  opacity: 0;
  filter: blur(var(--p14-reveal-blur));
  transition: opacity var(--p14-reveal-dur) var(--p14-reveal-ease),
        filter  var(--p14-reveal-dur) var(--p14-reveal-ease);
  transition-delay: 0ms;
}
.p14-card.is-resetting .p14-skeleton,
.p14-card.is-resetting .p14-content {
  transition: none !important;
}
.p14-content .p14-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  flex: none;
}
.p14-content .p14-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.p14-content .p14-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  line-height: 16px;
}
.p14-content .p14-email {
  font-size: 12px;
  color: var(--muted);
  line-height: 16px;
}
.p14-card.is-revealed .p14-skeleton {
  opacity: 0;
  filter: blur(var(--p14-reveal-blur));
}
.p14-card.is-revealed .p14-content {
  opacity: 1;
  filter: blur(0);
}

@media (max-width: 639px) {
.card-stage {
  right: 12px;
  width: auto;
  max-width: none;
}
}

@media (prefers-reduced-motion: reduce) {
.p14-skeleton,
.p14-content {
  transform: none !important;
  filter: none !important;
}
.p14-skeleton.is-pulsing .p14-sk-avatar,
.p14-skeleton.is-pulsing .p14-sk-name,
.p14-skeleton.is-pulsing .p14-sk-email {
  animation: none !important;
}
}

@keyframes p14-pulse {
      0%, 100% { opacity: 1; }
      50%      { opacity: var(--p14-pulse-min); }
    }

