// Shimmer text: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "15": {
          // Play/Pause the masked highlight sweep. While playing,
          // .is-shimmering loops the keyframes infinitely; Pause
          // removes the class and parks the band off-screen.
          // remove → reflow → add on Play restarts from 0 even
          // when the user mashes the button mid-sweep.
          var p15El = card.querySelector("[data-proto-shimmer]");
          if (!p15El) break;
          if (p15El.classList.contains("is-shimmering")) {
            p15El.classList.remove("is-shimmering");
            animateBtn.textContent = "Play";
          } else {
            p15El.classList.remove("is-shimmering");
            void p15El.offsetWidth;
            p15El.classList.add("is-shimmering");
            animateBtn.textContent = "Pause";
          }
          break;
        }
      }
      return;
    }
  });
})();

