// Tooltip open/close: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  (function initP17() {
    var groups = document.querySelectorAll("[data-proto-tooltip]");
    if (!groups.length) return;
    groups.forEach(function (group) {
      var tip = group.querySelector(".p17-tooltip");
      var text = group.querySelector(".p17-tooltip-text");
      var triggers = Array.prototype.slice.call(group.querySelectorAll(".p17-trigger"));
      if (!tip || !text || !triggers.length) return;
      function hide() {
        tip.setAttribute("data-show", "false");
        tip.setAttribute("aria-hidden", "true");
      }
      function place(trigger) {
        var showing = tip.getAttribute("data-show") === "true";
        text.textContent = trigger.getAttribute("data-tooltip") || "";
        var cs = getComputedStyle(tip);
        var width = Math.ceil(
          text.scrollWidth + parseFloat(cs.paddingLeft) + parseFloat(cs.paddingRight)
        );
        var g = group.getBoundingClientRect();
        var r = trigger.getBoundingClientRect();
        var x = (r.left - g.left) + r.width / 2 - width / 2;
        if (!showing) {
          // Snap the geometry while hidden so only the appear plays.
          tip.style.transition = "none";
          tip.style.width = width + "px";
          tip.style.setProperty("--p17-x", x + "px");
          void tip.offsetWidth;
          tip.style.transition = "";
        } else {
          tip.style.width = width + "px";
          tip.style.setProperty("--p17-x", x + "px");
        }
        tip.setAttribute("data-show", "true");
        tip.setAttribute("aria-hidden", "false");
      }
      triggers.forEach(function (t) {
        t.addEventListener("pointerenter", function () { place(t); });
        t.addEventListener("focus", function () { place(t); });
        t.addEventListener("blur", hide);
      });
      group.addEventListener("pointerleave", hide);
    });
  })();
})();

