// 3D tilt: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  (function initP19() {
    var tilt = document.getElementById("p19-tilt");
    var card = document.getElementById("p19-card");
    if (!tilt || !card) return;
    var reduce = window.matchMedia("(prefers-reduced-motion: reduce)");
    // Works for any pointer type. A mouse drives the tilt on hover;
    // touch / pen drive it while pressed (tap-hold-drag), since a
    // touch pointermove only fires while a finger is down.
    var enabled = !reduce.matches;

    var SPEED_REF = 1.2;
    var SPEED_MIN = 0.15;
    var SPEED_SMOOTH = 0.72;

    var lastX = null;
    var lastY = null;
    var lastT = null;
    var speedSmoothed = 0;

    function readNum(prop, fallback) {
      var v = parseFloat(getComputedStyle(card).getPropertyValue(prop));
      return isNaN(v) ? fallback : v;
    }
    function readMax() {
      return readNum("--p19-max", 40);
    }
    function speedTiltScale() {
      var sens = readNum("--p19-speed-sens", 0);
      if (sens <= 0) return 1;
      var t = Math.min(1, (speedSmoothed * sens) / SPEED_REF);
      return SPEED_MIN + (1 - SPEED_MIN) * t;
    }
    function reset() {
      tilt.classList.remove("is-hover");
      card.classList.remove("is-tilting");
      card.style.setProperty("--p19-rx", "0deg");
      card.style.setProperty("--p19-ry", "0deg");
      lastX = null;
      lastY = null;
      lastT = null;
      speedSmoothed = 0;
    }
    function begin(e) {
      if (!enabled) return;
      lastX = e.clientX;
      lastY = e.clientY;
      lastT = performance.now();
      speedSmoothed = 0;
    }
    tilt.addEventListener("pointerenter", begin);
    tilt.addEventListener("pointerdown", function (e) {
      if (!enabled) return;
      // Touch / pen: capture the pointer so the drag keeps targeting
      // the card even if the finger drifts past its edge.
      if (e.pointerType !== "mouse") {
        try { tilt.setPointerCapture(e.pointerId); } catch (err) {}
      }
      begin(e);
    });
    tilt.addEventListener("pointermove", function (e) {
      if (!enabled) return;
      var now = performance.now();
      if (lastT != null && lastX != null && lastY != null) {
        var dt = now - lastT;
        if (dt > 0) {
          var speed = Math.hypot(e.clientX - lastX, e.clientY - lastY) / dt;
          speedSmoothed = speedSmoothed * SPEED_SMOOTH + speed * (1 - SPEED_SMOOTH);
        }
      }
      lastX = e.clientX;
      lastY = e.clientY;
      lastT = now;

      var rect = tilt.getBoundingClientRect();
      var px = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      var py = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
      var max = readMax() * speedTiltScale();
      tilt.classList.add("is-hover");
      card.classList.add("is-tilting");
      card.style.setProperty("--p19-ry", ((px - 0.5) * max).toFixed(2) + "deg");
      card.style.setProperty("--p19-rx", ((0.5 - py) * max).toFixed(2) + "deg");
      card.style.setProperty("--p19-gx", (px * 100).toFixed(1) + "%");
      card.style.setProperty("--p19-gy", (py * 100).toFixed(1) + "%");
    });
    tilt.addEventListener("pointerup", reset);
    tilt.addEventListener("pointercancel", reset);
    tilt.addEventListener("pointerleave", function (e) {
      // Mouse: leaving the card flattens it. Touch already reset on up.
      if (e.pointerType === "mouse") reset();
    });

    function refresh() {
      enabled = !reduce.matches;
      reset();
    }
    if (reduce.addEventListener) {
      reduce.addEventListener("change", refresh);
    }
  })();
})();

