// Dropdown menu morph: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  (function initP20() {
    var morph = document.getElementById("p20-morph");
    var plus = document.getElementById("p20-plus");
    if (!morph || !plus) return;

    function setOpen(open) {
      var wasOpen = morph.getAttribute("data-open") === "true";
      morph.setAttribute("data-open", open ? "true" : "false");
      plus.setAttribute("aria-expanded", open ? "true" : "false");
      var menu = morph.querySelector(".p20-menu");
      if (menu) menu.setAttribute("aria-hidden", open ? "false" : "true");
      morph.classList.remove("is-closing");
      if (!open && wasOpen) {
        void morph.offsetWidth;
        morph.classList.add("is-closing");
      }
    }
    morph.addEventListener("animationend", function (e) {
      if (e.target === morph) morph.classList.remove("is-closing");
    });
    plus.addEventListener("click", function (e) {
      e.stopPropagation();
      setOpen(morph.getAttribute("data-open") !== "true");
    });
    document.addEventListener("click", function (e) {
      if (morph.getAttribute("data-open") !== "true") return;
      if (!morph.contains(e.target)) setOpen(false);
    });
    // Clicking anywhere in this card's stage while the menu is open
    // closes it — and we stop the event in the capture phase so the
    // card's "open code modal" click handler doesn't also fire.
    var stage = morph.closest(".card-stage");
    if (stage) {
      stage.addEventListener("click", function (e) {
        if (morph.getAttribute("data-open") !== "true") return;
        if (plus.contains(e.target)) return;
        e.stopPropagation();
        setOpen(false);
      }, true);
    }
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && morph.getAttribute("data-open") === "true") {
        setOpen(false);
      }
    });
  })();
})();

