// Like button: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 23: Like button particle seeding ────────────
     Randomises each of the 8 dots' trajectory / velocity / delay /
     end-scale / size on every like so the burst never repeats. */
  function p23Seed(likeEl) {
    var dots = likeEl.querySelectorAll(".p23-particles i");
    var dist = readMs("--p23-particle-dist", 20);
    for (var i = 0; i < dots.length; i++) {
      var baseAngle = (360 / dots.length) * i;
      var angle = baseAngle + (Math.random() * 2 - 1) * 16; // ±16°
      var mag = dist * (0.68 + Math.random() * 0.5);
      var rad = angle * Math.PI / 180;
      var s = dots[i].style;
      s.setProperty("--px", (Math.cos(rad) * mag).toFixed(2) + "px");
      s.setProperty("--py", (Math.sin(rad) * mag).toFixed(2) + "px");
      s.setProperty("--pdur",
        "calc(var(--p23-particle-dur) * " + (0.78 + Math.random() * 0.44).toFixed(3) + ")");
      s.setProperty("--pdelay", (Math.random() * 70).toFixed(0) + "ms");
      s.setProperty("--p-end-scale", (0.35 + Math.random() * 0.4).toFixed(2));
      s.setProperty("--psize", (0.6 + Math.random() * 0.8).toFixed(2));
    }
  }

  document.addEventListener("click", function (e) {
    /* --- Prototype 23: Like button (fill + pop + particle burst) --- */
    var likeBtn = e.target.closest("[data-proto-like]");
    if (likeBtn) {
      var wasLiked = likeBtn.getAttribute("data-liked") === "true";
      if (wasLiked) {
        likeBtn.setAttribute("data-liked", "false");
        likeBtn.setAttribute("aria-pressed", "false");
        likeBtn.classList.remove("is-bursting");
        return;
      }
      likeBtn.setAttribute("data-liked", "true");
      likeBtn.setAttribute("aria-pressed", "true");
      likeBtn.classList.remove("is-bursting");
      p23Seed(likeBtn);
      // eslint-disable-next-line no-unused-expressions
      likeBtn.offsetWidth;
      likeBtn.classList.add("is-bursting");
      if (likeBtn._burstT) window.clearTimeout(likeBtn._burstT);
      likeBtn._burstT = window.setTimeout(function () {
        likeBtn.classList.remove("is-bursting");
      }, readMs("--p23-particle-dur", 600) * 1.25 + 120);
      return;
    }
  });
})();

