    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  document.addEventListener("click", function (e) {
    /* --- Prototype 25: Checkbox (click box or label) --- */
    var p25field = e.target.closest(".p25-field");
    if (p25field) {
      var p25box = p25field.querySelector("[data-proto-checkbox]");
      if (p25box) {
