     translates up (spins·10 + digit) cells to spin then land.
     A directional (vertical-only) SVG motion blur decays to 0 as
     each reel settles (rAF, since SVG attrs aren't transitionable);
     columns land left-to-right via a per-strip transition-delay. */
  var P26_BLUR_MAX = 10;
  function p26ReadNum(name, fallback) {
    var v = parseFloat(
      getComputedStyle(document.documentElement).getPropertyValue(name));
    return isNaN(v) ? fallback : v;
  }
  function p26EnsureDefs() {
    if (document.getElementById("p26-blur-defs")) return;
    var svgNS = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("id", "p26-blur-defs");
    svg.setAttribute("aria-hidden", "true");
    svg.style.position = "absolute";
    svg.style.width = "0";
    svg.style.height = "0";
    svg.style.overflow = "hidden";
    var defs = document.createElementNS(svgNS, "defs");
    for (var i = 0; i < P26_BLUR_MAX; i++) {
      var filter = document.createElementNS(svgNS, "filter");
      filter.setAttribute("id", "p26-blur-" + i);
      filter.setAttribute("x", "-20%");
      filter.setAttribute("y", "-150%");
      filter.setAttribute("width", "140%");
      filter.setAttribute("height", "400%");
      var fe = document.createElementNS(svgNS, "feGaussianBlur");
      fe.setAttribute("id", "p26-blur-fe-" + i);
      fe.setAttribute("stdDeviation", "0 0");
      filter.appendChild(fe);
      defs.appendChild(filter);
    }
    svg.appendChild(defs);
    document.body.appendChild(svg);
  }
  function p26Build(el, str, spins, rows) {
    el.innerHTML = "";
    var cols = [];
    var total = (spins + 1) * 10 + rows;
    for (var c = 0; c < str.length; c++) {
      var ch = str[c];
      if (ch >= "0" && ch <= "9") {
        var col = document.createElement("span");
        col.className = "p26-col";
        var strip = document.createElement("span");
        strip.className = "p26-col-strip";
        for (var k = 0; k < total; k++) {
          var cell = document.createElement("span");
          cell.className = "p26-digit";
          cell.textContent = String(k % 10);
          strip.appendChild(cell);
        }
        col.appendChild(strip);
        el.appendChild(col);
        var idx = cols.length % P26_BLUR_MAX;
        strip.style.filter = "url(#p26-blur-" + idx + ")";
        cols.push({ strip: strip, digit: +ch, blurIndex: idx });
      } else {
        var sep = document.createElement("span");
        sep.className = "p26-sep";
        sep.textContent = ch;
        el.appendChild(sep);
      }
    }
    return cols;
  }
  function p26CenterY(index, cell, rows) {
    return -((index - Math.floor(rows / 2)) * cell);
  }
  function p26SetBlur(blurIndex, y) {
    var fe = document.getElementById("p26-blur-fe-" + blurIndex);
    if (fe) fe.setAttribute("stdDeviation", "0 " + y);
  }
  function p26Spin(el) {
    p26EnsureDefs();
    var target = Math.round(p26ReadNum("--p26-target", 100));
    var str = target.toLocaleString("en-US");
    var spins = Math.max(1, Math.round(p26ReadNum("--p26-spins", 3)));
    var cell = p26ReadNum("--p26-cell", 30);
    var rows = Math.max(1, Math.round(p26ReadNum("--p26-rows", 1)));
    var blurAmt = p26ReadNum("--p26-spin-blur", 3);
    var dur = readMs("--p26-dur", 1400);
    var stagger = readMs("--p26-stagger", 90);
    var ease = getComputedStyle(document.documentElement)
      .getPropertyValue("--p26-ease").trim() || "cubic-bezier(0.16, 1, 0.3, 1)";
    var reduce = window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    el.setAttribute("aria-label", str);
    var cols = p26Build(el, str, spins, rows);
    var startY = p26CenterY(Math.floor(rows / 2), cell, rows);
    cols.forEach(function (c) {
      c.strip.style.transition = "none";
      c.strip.style.transform = "translateY(" + startY + "px)";
      p26SetBlur(c.blurIndex, reduce ? 0 : blurAmt);
    });
    // eslint-disable-next-line no-unused-expressions
    el.offsetWidth;
    cols.forEach(function (c, i) {
      var delay = i * stagger;
      c.strip.style.transition = "transform " + dur + "ms " + ease + " " + delay + "ms";
      c.strip.style.transform =
        "translateY(" + p26CenterY(spins * 10 + c.digit, cell, rows) + "px)";
    });
    if (el._p26RafId) window.cancelAnimationFrame(el._p26RafId);
    if (reduce) return;
    var t0 = performance.now();
    var maxEnd = (cols.length - 1) * stagger + dur;
    (function tick() {
      var t = performance.now() - t0;
      cols.forEach(function (c, i) {
        var local = Math.min(1, Math.max(0, (t - i * stagger) / dur));
        p26SetBlur(c.blurIndex, (blurAmt * (1 - local)).toFixed(2));
      });
      if (t < maxEnd + 40) {
        el._p26RafId = window.requestAnimationFrame(tick);
      } else {
        cols.forEach(function (c) { p26SetBlur(c.blurIndex, 0); });
        el._p26RafId = null;
      }
    })();
  }
  // Resting state: render a static "0" in every reel on load.
  (function initP26Reels() {
    p26EnsureDefs();
    var reels = document.querySelectorAll("[data-proto-reel]");
    var cell = p26ReadNum("--p26-cell", 30);
    var rows = Math.max(1, Math.round(p26ReadNum("--p26-rows", 1)));
    reels.forEach(function (el) {
      el.setAttribute("aria-label", "0");
      var cols = p26Build(el, "0", 1, rows);
      cols.forEach(function (c) {
        c.strip.style.transform =
          "translateY(" + p26CenterY(c.digit, cell, rows) + "px)";
        p26SetBlur(c.blurIndex, 0);
      });
    });
  })();

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "26": {
          var reel = card.querySelector("[data-proto-reel]");
          if (reel) p26Spin(reel);
          break;
        }
      }
      return;
    }
  });
})();

