:root {
  --text: #0d0d0d;
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",
        Roboto, Helvetica, Arial, sans-serif;
  --p27-dur: 350ms;
  --p27-travel: 14.66px;
  --p27-ov1: 1px;
  --p27-ov2: 0px;
  --p27-track-dur: 0ms;
  --p27-ease: cubic-bezier(0.34, 1.35, 0.64, 1);
}

html[data-theme="dark"] {
  --text: #ffffff;
}

/* The library card, at its size: the stage of the card on library.html. */
:where(.card), :where(.card) *, :where(.card) *::before, :where(.card) *::after { box-sizing: border-box; margin: 0; padding: 0; }
.card { position: relative; width: 296px; height: 260px; color: var(--text); font-family: var(--font-sans); }
.card > .card-stage { inset: 0; width: auto; height: auto; max-width: none; border-radius: 0; }
.card > .card-stage::after { content: none; }

.card-stage {
  position: absolute;
  left: 12px;
  top: 12px;
  width: 296px;
  max-width: calc(100% - 24px);
  height: 260px;
  border-radius: 14px;
  overflow: hidden;
  background: var(--stage-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.card-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px var(--stage-border);
  pointer-events: none;
  z-index: 10;
}
html[data-theme="dark"] .card-stage {
  background: #131313;
}
html[data-theme="dark"] .card-stage::after {
  box-shadow: inset 0 0 0 1px rgba(191, 192, 203, 0.08);
}
.stage-inner {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 56px;
}
.stage-inner--no-btn {
  padding-bottom: 0;
}
.p27-switch {
  position: relative;
  width: 44px;
  height: 22px;
  border: 0;
  padding: 0;
  cursor: pointer;
  border-radius: 122px;
  background: var(--p27-track-off, rgba(0, 0, 0, 0.12));
  -webkit-tap-highlight-color: transparent;
  transition: background var(--p27-track-dur) var(--p27-ease);
}
html[data-theme="dark"] .p27-switch {
  --p27-track-off: rgba(255, 255, 255, 0.15);
}
.p27-switch[data-on="true"] {
  background: rgba(0, 60, 255, 0.8);
}
.p27-thumb {
  position: absolute;
  left: 3.67px;
  top: 3.67px;
  width: 22px;
  height: 14.67px;
  border-radius: 122px;
  background: #fff;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05),
        0 4px 42px rgba(0, 0, 0, 0.06);
  translate: 0 0;
  will-change: translate;
}
.p27-switch[data-on="true"] .p27-thumb {
  translate: var(--p27-travel) 0;
}
.p27-switch.is-init[data-on="true"] .p27-thumb {
  animation: p27-on var(--p27-dur) var(--p27-ease) both;
}
.p27-switch.is-init[data-on="false"] .p27-thumb {
  animation: p27-off var(--p27-dur) var(--p27-ease) both;
}
.p27-switch::before {
  content: "";
  position: absolute;
  inset: -16px;
}

@media (prefers-reduced-motion: reduce) {
.p27-thumb {
  animation: none !important;
}
}

@media (max-width: 639px) {
.card-stage {
  right: 12px;
  width: auto;
  max-width: none;
}
}

@keyframes p27-on {
      0%   { translate: 0 0; }
      55%  { translate: calc(var(--p27-travel) + var(--p27-ov1)) 0; }
      80%  { translate: calc(var(--p27-travel) - var(--p27-ov2)) 0; }
      100% { translate: var(--p27-travel) 0; }
    }

@keyframes p27-off {
      0%   { translate: var(--p27-travel) 0; }
      55%  { translate: calc(0px - var(--p27-ov1)) 0; }
      80%  { translate: var(--p27-ov2) 0; }
      100% { translate: 0 0; }
    }

