// Thinking states: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 28: AI thinking states ──────────────────────
     One status line cycles on its own: the shimmer runs while a
     state holds, then the line swaps with the text-swap motion
     (exit up + blur, enter from below). textContent and
     data-text move together so the shimmer's ::before copy
     always matches the visible line. */
  (function initP28Think() {
    var box = document.querySelector("[data-proto-think]");
    if (!box) return;
    var live = box.querySelector(".p28-text");
    if (!live) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    var STATES = [
      "Setting up a workplace",
      "Running a command",
      "Browsing files",
    ];
    var i = 0;
    var timer = 0;
    // The card rests on its first state: a grid of cards all
    // cycling at once is noise, so motion starts on demand.
    box.classList.add("is-paused");
    box._p28Toggle = function () {
      var paused = box.classList.toggle("is-paused");
      window.clearTimeout(timer);
      // Clearing the timer mid-swap would strand the outgoing
      // line on top of the live one, so drop it here.
      Array.prototype.forEach.call(box.querySelectorAll(".p28-text.is-exit"), function (el) {
        if (el.parentNode) el.parentNode.removeChild(el);
      });
      if (!paused) cycle();
      return paused;
    };
    function cycle() {
      timer = window.setTimeout(function () {
        var swap = readMs("--p28-swap-dur", 150);
        var gap = readMs("--p28-swap-gap", 50);
        var leaving = live;
        i = (i + 1) % STATES.length;

        // Float the outgoing line over the box and start its exit.
        leaving.classList.add("is-exit");

        var next = document.createElement("span");
        next.className = "p28-text is-enter-start";
        next.textContent = STATES[i];
        next.setAttribute("data-text", STATES[i]);
        box.appendChild(next);
        live = next;

        function release() {
          // eslint-disable-next-line no-unused-expressions
          next.offsetWidth;
          next.classList.remove("is-enter-start");
        }
        if (gap > 0) window.setTimeout(release, gap);
        else release();

        timer = window.setTimeout(function () {
          if (leaving.parentNode) leaving.parentNode.removeChild(leaving);
          cycle();
        }, swap + gap);
      }, readMs("--p28-hold", 2000));
    }
  })();

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "28": {
          var think = card.querySelector("[data-proto-think]");
          if (think && think._p28Toggle) animateBtn.textContent = think._p28Toggle() ? "Play" : "Pause";
          break;
        }
      }
      return;
    }
  });
})();

