// Reasoning stream: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 29: agent reasoning stream ──────────────────
     The transcript renders twice back-to-back; the offset steps
     up --p29-lines lines per hold and wraps by one copy's height
     the moment a step lands past it — the clone makes the wrap
     invisible. Runs continuously on the card. */
  (function initP29Stream() {
    var scroll = document.querySelector("[data-proto-reason]");
    if (!scroll) return;
    var text = scroll.querySelector(".p29-text");
    if (!text) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    // Second copy carries the wrap.
    scroll.appendChild(text.cloneNode(true));
    var offset = 0;
    var timer = 0;
    var paused = true;
    scroll._p29Toggle = function () {
      paused = !paused;
      window.clearTimeout(timer);
      // Pausing holds the transcript where it stopped, so playing
      // again continues rather than rewinds.
      if (!paused) step();
      return paused;
    };
    function step() {
      timer = window.setTimeout(function () {
        var lineH = parseFloat(getComputedStyle(text).lineHeight) || 18.2;
        var stepPx = lineH * readMs("--p29-lines", 2);
        var dur = readMs("--p29-step-dur", 500);
        var ease = getComputedStyle(document.documentElement)
          .getPropertyValue("--p29-ease").trim() || "ease-out";
        offset += stepPx;
        scroll.style.transition = "transform " + dur + "ms " + ease;
        scroll.style.transform = "translateY(" + (-offset) + "px)";
        timer = window.setTimeout(function () {
          // Wrap by one copy the moment a step lands past it; the
          // clone underneath makes the jump invisible.
          var copyH = text.offsetHeight;
          if (offset >= copyH) {
            offset -= copyH;
            scroll.style.transition = "none";
            scroll.style.transform = "translateY(" + (-offset) + "px)";
            // eslint-disable-next-line no-unused-expressions
            scroll.offsetWidth;
          }
          step();
        }, dur + 30);
      }, readMs("--p29-hold", 840));
    }
  })();

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "29": {
          var reason = card.querySelector("[data-proto-reason]");
          if (reason && reason._p29Toggle) animateBtn.textContent = reason._p29Toggle() ? "Play" : "Pause";
          break;
        }
      }
      return;
    }
  });
})();

