// Streaming text: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 30: streaming text ──────────────────────────
     The paragraph rests fully readable; Animate wipes it back to
     nothing and resolves the words in order through a small
     cross-blur. The word spans are built once at load. */
  function p30Replay(block) {
    var spans = block._p30Spans;
    if (!spans) return;
    if (block._p30Timer) window.clearTimeout(block._p30Timer);
    // Snap back to nothing without animating the wipe itself.
    spans.forEach(function (s) {
      s.style.transition = "none";
      s.classList.remove("is-in");
    });
    // eslint-disable-next-line no-unused-expressions
    block.offsetWidth;
    spans.forEach(function (s) { s.style.transition = ""; });
    (function stream(n) {
      if (n >= spans.length) return;
      spans[n].classList.add("is-in");
      block._p30Timer = window.setTimeout(function () {
        stream(n + 1);
      }, readMs("--p30-word-gap", 60));
    })(0);
  }
  (function initP30Stream() {
    var blocks = document.querySelectorAll("[data-proto-stream]");
    blocks.forEach(function (block) {
      var words = block.textContent.trim().split(/\s+/);
      block.textContent = "";
      block._p30Spans = words.map(function (w, idx) {
        var s = document.createElement("span");
        s.className = "p30-w is-in";
        s.textContent = w;
        block.appendChild(s);
        if (idx < words.length - 1) block.appendChild(document.createTextNode(" "));
        return s;
      });
    });
  })();

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "30": {
          var stream = card.querySelector("[data-proto-stream]");
          if (stream) p30Replay(stream);
          break;
        }
      }
      return;
    }
  });
})();

