// Matrix dot loader: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 33: matrix dot loaders ──────────────────────
     Delay tables per variant, all riding the same pulse cycle.
     Twinkle's order is baked (not random) so every dot fires
     exactly once per cycle; the centre cells of the orbit
     variant hold steady so the ring reads as the mover. */
  (function initP33Loaders() {
    var CORNERS = [0, 3, 12, 15];
    // Clockwise perimeter (corner-less ring), then centre cells.
    var RING = [1, 2, 7, 11, 14, 13, 8, 4];
    var INNER = [5, 6, 9, 10];
    var TWINKLE = [7, 2, 11, 5, 14, 9, 0, 12, 3, 15, 6, 10, 13, 1, 8, 4];
    document.querySelectorAll(".p33-loader").forEach(function (loader) {
      var variant = loader.getAttribute("data-variant");
      var rounded = loader.getAttribute("data-rounded") === "true";
      var cycle = readMs("--p33-cycle", 1200);
      for (var idx = 0; idx < 16; idx++) {
        var dot = document.createElement("i");
        var col = idx % 4;
        if (rounded && CORNERS.indexOf(idx) !== -1) {
          dot.className = "is-gap";
        } else if (variant === "scan") {
          dot.style.setProperty("--d", String(Math.round(col * (cycle / 10))));
        } else if (variant === "twinkle") {
          dot.style.setProperty("--d", String(Math.round(TWINKLE[idx] * (cycle / 16))));
        } else if (variant === "orbit") {
          var k = RING.indexOf(idx);
          if (k !== -1) {
            dot.style.setProperty("--d", String(Math.round(k * (cycle / 8))));
          } else {
            // Centre holds steady under the orbiting ring.
            dot.style.animation = "none";
          }
        } else if (variant === "pulse") {
          var ring = INNER.indexOf(idx) !== -1 ? 0 : 1;
          dot.style.setProperty("--d", String(Math.round(ring * (cycle * 0.16))));
        }
        loader.appendChild(dot);
      }
    });
  })();
})();

