html[data-theme="dark"] .card-stage {
  background: #131313;
}
html[data-theme="dark"] .card-stage::after {
  box-shadow: inset 0 0 0 1px rgba(191, 192, 203, 0.08);
}
.btn-animate {
  appearance: none;
  -webkit-appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 20px;
  height: 36px;
  padding: 6px 12px;
  border: 0;
  border-radius: 40px;
  font-family: var(--font-sans);
  font-weight: 500;
  font-size: 13px;
  line-height: 16px;
  color: var(--animate-text);
  background-color: var(--animate-bg-tint);
  background-image: linear-gradient(90deg, var(--animate-bg) 0%, var(--animate-bg) 100%);
  cursor: pointer;
  white-space: nowrap;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease, filter 0.15s ease;
  z-index: 5;
  flex-shrink: 0;
}
html[data-theme="dark"] .btn-animate {
  background-color: transparent;
  background-image: none;
  background: var(--animate-bg);
}
.btn-animate:hover {
  filter: brightness(0.98);
}
html[data-theme="dark"] .btn-animate:hover {
  background: var(--animate-bg-hover);
  filter: none;
}
html[data-theme="dark"] .btn-animate:active {
  background: var(--animate-bg-pressed);
  filter: none;
}
html[data-theme="dark"] .btn-animate:disabled {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
  cursor: not-allowed;
}
html[data-theme="dark"] .btn-animate:disabled:hover {
  background: var(--animate-bg);
  color: var(--animate-text-disabled);
}
.btn-animate:active {
  filter: brightness(0.95);
}
.btn-animate:focus-visible {
  outline: 2px solid var(--animate-text);
  outline-offset: 2px;
}
.btn-animate[data-proto="15"] {
  min-width: 75px;
}
.stage-inner {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: 56px;
}
.p34-stage-inner {
  align-items: flex-end;
  padding-bottom: 78px;
}
.p34-stack {
  position: relative;
  width: 261px;
  height: 46px;
}
.p34-banner {
  position: absolute;
  left: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 261px;
  height: 46px;
  padding: 0 16px;
  background: var(--surface-bg);
  border-radius: 52px;
  box-shadow: var(--material-shadow);
  transform-origin: 50% 50%;
  filter: blur(0);
  will-change: transform, opacity, filter;
  transition: transform var(--p34-open-dur) var(--p34-ease),
        opacity var(--p34-open-dur) var(--p34-ease),
        filter var(--p34-open-dur) var(--p34-ease);
}
.p34-banner[data-depth="0"] {
  z-index: 3;
  transform: translateY(0) scale(1);
  opacity: 1;
}
.p34-banner[data-depth="1"] {
  z-index: 2;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--p34-peek) * -1))
                 scale(calc(1 - var(--p34-depth-scale)));
  opacity: calc(1 - var(--p34-depth-fade));
  filter: blur(var(--p34-depth1-blur));
}
.p34-banner[data-depth="2"] {
  z-index: 1;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--p34-peek) * -2))
                 scale(calc(1 - var(--p34-depth-scale) * 2));
  opacity: calc(1 - var(--p34-depth-fade) * 1.6);
  filter: blur(var(--p34-depth2-blur));
}
.p34-stack.is-spread .p34-banner[data-depth="1"],
.p34-stack.is-spread .p34-banner[data-depth="2"] {
  opacity: 1;
  filter: blur(0);
}
.p34-stack.is-spread .p34-banner[data-depth="1"] {
  transform: translateY(calc((46px + var(--p34-spread-gap)) * -1)) scale(1);
}
.p34-stack.is-spread .p34-banner[data-depth="2"] {
  transform: translateY(calc((46px + var(--p34-spread-gap)) * -2)) scale(1);
}
.p34-banner.is-enter {
  transition: none;
  transform: translateY(var(--p34-distance)) scale(var(--p34-scale-in));
  opacity: 0;
  filter: blur(var(--p34-blur));
}
.p34-banner.is-leaving {
  z-index: 0;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--p34-peek) * -3))
                 scale(calc(1 - var(--p34-depth-scale) * 3));
  opacity: 0;
  filter: blur(var(--p34-blur));
  transition: transform var(--p34-close-dur) var(--p34-ease),
        opacity var(--p34-close-dur) var(--p34-ease),
        filter var(--p34-close-dur) var(--p34-ease);
}
.p34-avatar {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--skeleton);
}
.p34-bar {
  width: 178px;
  height: 14px;
  border-radius: 4px;
  background: var(--skeleton);
}

@media (prefers-reduced-motion: reduce) {
.p34-banner {
  transform: none !important;
  filter: none !important;
  transition: none !important;
}
}

@media (max-width: 639px) {
.card-stage {
  right: 12px;
  width: auto;
  max-width: none;
}
}

