// Banner stacking: the library card's own script, from library.html.
(function () {
  function findCard(el) { return el.closest("[data-proto-card]"); }

  function readMs(name, fallback) {
    var raw = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (!raw) return fallback;
    if (raw.slice(-2) === "ms") return parseFloat(raw);
    if (raw.slice(-1) === "s")  return parseFloat(raw) * 1000;
    var n = parseFloat(raw);
    return isNaN(n) ? fallback : n;
  }

  /* ── Prototype 34: banner stacking ─────────────────────────
     Sonner-style: a new banner rises in at depth 0; everything
     already stacked steps one depth back (smaller, higher,
     dimmer — pure data-depth swap, CSS transitions the rest).
     A fourth banner pushes the oldest out entirely. */
  function p34Add(stack) {
    var banners = stack._p34Banners || (stack._p34Banners = []);
    var el = document.createElement("div");
    el.className = "p34-banner is-enter";
    el.setAttribute("data-depth", "0");
    el.innerHTML = '<span class="p34-avatar"></span><span class="p34-bar"></span>';
    banners.unshift(el);
    stack.appendChild(el);
    banners.forEach(function (b, i) {
      if (i === 0) return;
      if (i > 2) {
        if (!b.classList.contains("is-leaving")) {
          b.classList.add("is-leaving");
          window.setTimeout(function () {
            if (b.parentNode) b.parentNode.removeChild(b);
          }, readMs("--p34-close-dur", 250) + 60);
        }
      } else {
        b.setAttribute("data-depth", String(i));
      }
    });
    stack._p34Banners = banners.slice(0, 3).concat(
      banners.slice(3).filter(function (b) { return !b.classList.contains("is-leaving"); })
    );
    // Flush the pre-open rest state, then release it in the same
    // task. A rAF hop would be skipped whenever the frame clock is
    // throttled, and the banner would land with no motion at all.
    // eslint-disable-next-line no-unused-expressions
    el.offsetWidth;
    el.classList.remove("is-enter");
  }
  (function initP34Stacks() {
    var stacks = document.querySelectorAll("[data-proto-stack]");
    stacks.forEach(function (stack) {
      // Seed a resting stack of three so the card reads at a
      // glance — no .is-enter, they are simply there on load. The
      // newest-first array matches three manual adds exactly, so
      // the next Add pushes these back and drops the oldest.
      var seeded = [];
      for (var d = 2; d >= 0; d--) {
        var b = document.createElement("div");
        b.className = "p34-banner";
        b.setAttribute("data-depth", String(d));
        b.innerHTML = '<span class="p34-avatar"></span><span class="p34-bar"></span>';
        stack.appendChild(b);
        seeded.unshift(b);
      }
      stack._p34Banners = seeded;
      /* Spread state is decided from the pointer's position alone:
         over the collapsed stack it opens, and it holds until the
         pointer leaves the taller column the spread occupies. Both
         halves are geometry rather than :hover / pointerenter —
         the gaps between spread banners belong to no element, and
         boundary events would also fire when a banner animates in
         under a still pointer, spreading the stack on its own. */
      var stage = stack.parentElement;
      function spreadHeight() {
        var gap = parseFloat(getComputedStyle(document.documentElement)
          .getPropertyValue("--p34-spread-gap")) || 8;
        return (stack.offsetHeight + gap) * 2;
      }
      function within(e, above) {
        var r = stack.getBoundingClientRect();
        return e.clientX >= r.left && e.clientX <= r.right &&
          e.clientY <= r.bottom && e.clientY >= r.top - above;
      }
      stage.addEventListener("pointermove", function (e) {
        if (stack.classList.contains("is-spread")) {
          if (!within(e, spreadHeight())) stack.classList.remove("is-spread");
        } else if (within(e, 0)) {
          stack.classList.add("is-spread");
        }
      });
      stage.addEventListener("pointerleave", function () {
        stack.classList.remove("is-spread");
      });
    });
  })();

  document.addEventListener("click", function (e) {
    var animateBtn = e.target.closest("button[data-proto]");
    if (animateBtn) {
      var proto = animateBtn.getAttribute("data-proto");
      var card = findCard(animateBtn);
      if (!card) return;
      switch (proto) {
        case "34": {
          var stack = card.querySelector("[data-proto-stack]");
          if (stack) p34Add(stack);
          break;
        }
      }
      return;
    }
  });
})();
